export function softmax(logits) {
    const out = new Float32Array(logits.length);
    if (!logits.length)
        return out;
    let max = -Infinity;
    for (const v of logits)
        if (v > max)
            max = v;
    let sum = 0;
    for (let i = 0; i < logits.length; i += 1) {
        out[i] = Math.exp(logits[i] - max);
        sum += out[i];
    }
    if (sum <= 0)
        return out;
    for (let i = 0; i < out.length; i += 1)
        out[i] /= sum;
    return out;
}
